const POSITION_BONUS_LABELS={
 power:"파워",contact:"정확",eye:"선구",patience:"인내",baserun:"주루",fielding:"수비",
 velocity:"구속",break:"변화",stuff:"구위",control:"제구",stamina:"지구력"
};
function cumulativeStageBonus(stageMap,level,meta){
 const out={};meta.forEach(([k])=>out[k]=0);
 level=Math.max(0,Math.min(20,Number(level)||0));
 for(let lv=1;lv<=level;lv++){
   const row=stageMap[lv]||{};
   for(const [k,v] of Object.entries(row))if(k in out)out[k]+=Number(v)||0;
 }
 return out;
}
function positionBaseForSlot(slot,level,role){
 const meta=role==="pitcher"?PIT_META:BAT_META;
 const stageMap=POSITION_STAGE_BY_SLOT[slot];
 if(stageMap)return cumulativeStageBonus(stageMap,level,meta);
 return scaledPositionBase(role==="pitcher"?POSITION_BASE_PIT:POSITION_BASE_BAT,level);
}

function positionBaseSummary(slot,role){
 const meta=role==="pitcher"?PIT_META:BAT_META;
 const vals=positionBaseForSlot(slot,20,role);
 return meta.map(([k,label])=>`${label}${vals[k]||0}`).join(" · ");
}
function allowedPositionBonusKeys(role){
 return role==="pitcher"
  ?["velocity","break","stuff","control","stamina","fielding"]
  :["power","contact","eye","patience","baserun","fielding"];
}
function randomPositionBonusRoll(role,milestone=5){
 const key=role==="pitcher"?(Number(milestone)===15?"stuff":"break"):(Number(milestone)===15?"contact":"power");
 return {key,stats:{[key]:3},amount:3};
}
function normalizePositionBonusRoll(raw,role,milestone=5){return randomPositionBonusRoll(role,milestone);}
function getPositionBonusRoll(slot,milestone,mode=currentMode){
 const L=ensureLineupState(mode),role=PITCH.includes(slot)?"pitcher":"batter";
 if(!L.positionTrainingChoices[slot])L.positionTrainingChoices[slot]={};
 const roll=normalizePositionBonusRoll(L.positionTrainingChoices[slot][String(milestone)],role,milestone);
 L.positionTrainingChoices[slot][String(milestone)]=roll;
 return roll;
}
function rerollPositionBonus(slot,milestone){
 const L=lineup(),role=PITCH.includes(slot)?"pitcher":"batter";
 if(!L.positionTrainingChoices)L.positionTrainingChoices={};
 if(!L.positionTrainingChoices[slot])L.positionTrainingChoices[slot]={};
 L.positionTrainingChoices[slot][String(milestone)]=randomPositionBonusRoll(role,milestone);
 renderSetdeckPosition();renderSquad();
}
function setPositionBonusManual(slot,milestone,key,amount){
 const L=lineup(),role=PITCH.includes(slot)?"pitcher":"batter";
 const allowed=allowedPositionBonusKeys(role);
 amount=Math.max(1,Math.min(3,Number(amount)||1));
 if(!allowed.includes(key))return;
 if(!L.positionTrainingChoices)L.positionTrainingChoices={};
 if(!L.positionTrainingChoices[slot])L.positionTrainingChoices[slot]={};
 L.positionTrainingChoices[slot][String(milestone)]={key,amount};
 renderSetdeckPosition();renderSquad();
}



