const VIEW_MODE_KEY="v26_view_mode";
let forcedViewMode=localStorage.getItem(VIEW_MODE_KEY); // mobile | desktop | null(auto)
function deviceViewMode(){
 return window.matchMedia("(max-width:760px)").matches?"mobile":"desktop";
}
function resolvedViewMode(){
 return forcedViewMode==="mobile"||forcedViewMode==="desktop"?forcedViewMode:deviceViewMode();
}
function applyViewMode(mode){
 mode=mode==="mobile"?"mobile":"desktop";
 document.body.classList.toggle("view-mobile",mode==="mobile");
 document.body.classList.toggle("view-desktop",mode==="desktop");
 const text=document.getElementById("viewToggleText"),sub=document.getElementById("viewToggleSub");
 if(text)text.textContent=mode==="mobile"?"🖥️ PC 보기":"📱 모바일 보기";
 if(sub)sub.textContent=mode==="mobile"?"현재 모바일 화면":"현재 PC 화면";
}
function toggleViewMode(){
 const current=document.body.classList.contains("view-mobile")?"mobile":"desktop";
 const next=current==="mobile"?"desktop":"mobile";
 forcedViewMode=next;
 localStorage.setItem(VIEW_MODE_KEY,next);
 applyViewMode(next);
 window.scrollTo({top:0,behavior:"smooth"});
}
function initViewMode(){
 applyViewMode(resolvedViewMode());
 window.addEventListener("resize",()=>{
   if(!forcedViewMode)applyViewMode(deviceViewMode());
 });
}

