function cardStars(p){
 if(p.custom)return Number(p.stars);
 const f=family(p);
 if(f==="signature"||f==="national"||f==="allstar")return 5;
 if(f==="impact")return 4;
 if(f==="gold"){
   const key=`${p.name}|${String(p.year??"").padStart(2,"0")}`;
   return GOLD_FOUR_STAR_KEYS.has(key)?4:5;
 }
 if(f==="season"&&Number.isInteger(Number(p.stars))&&Number(p.stars)>=1&&Number(p.stars)<=5)return Number(p.stars);
 if(f==="live"){
   if(Number.isInteger(Number(p.stars))&&Number(p.stars)>=1&&Number(p.stars)<=5)return Number(p.stars);
   const ovr=Number(p.ovr)||0;
   return ovr>=70?5:ovr>=64?4:3;
 }
 return null;
}

const ALLSTAR_GROUPS={
 dream:new Set(["두산","롯데","삼성","SSG","KT"]),
 nanum:new Set(["LG","KIA","키움","NC","한화"])
};
function allstarGroup(team){
 if(ALLSTAR_GROUPS.dream.has(team))return "dream";
 if(ALLSTAR_GROUPS.nanum.has(team))return "nanum";
 return "";
}
function hasPreferredTeam(){return PREFERRED_TEAM_OPTIONS.includes(preferredTeam)}
function effectiveSetdeckScore(p){
 const f=family(p),year=Number(p.year),pastSeason=Number.isFinite(year)&&year>0&&(year<=25||(year>=1900&&year<=2025));
 const pref=canonicalPreferredTeam();
 if(!pref)return 0;
 if(!["gold","allstar"].includes(f)&&effectiveTeam(p)!==pref)return 0;
 if(f==="allstar"){
   const own=p.team===pref;
   const sameGroup=!own&&allstarGroup(p.team)&&allstarGroup(p.team)===allstarGroup(pref);
   const currentScore=own?8:sameGroup?4:2;
   return pastSeason?Math.floor(currentScore/2):currentScore;
 }
 const base=Number(p.setdeck);
 if(!Number.isFinite(base))return null;
 if(f==="live"&&(year===25||year===2025))return Math.floor(base/2);
 if(f==="live"&&pastSeason)return base;
 const g=getGrowth(p),[initial]=specialBounds(p,g.faTeam);
 if(isNationalWildcard(p,g))return Math.max(1,Math.min(7,Number(g.special)||1));
 return base-(isFa(p,g)?3:0)+Math.max(0,Number(g.special||0)-initial);
}


function isYearlessImpact(p){return String(p?.type||"").trim()==="임팩트"||family(p)==="impact"}
function isTop3Card(p){return String(p?.series||"").trim().toUpperCase()==="TOP3"||String(p?.impactSeries||"").trim().toUpperCase()==="TOP3"}
function displayYear(p){if(isTop3Card(p)&&p.year!==null&&p.year!==undefined&&p.year!=="")return normalizeYearKey(p.year);return isYearlessImpact(p)?"":(p.year??"")}
function normalizeYearKey(value){
 if(value===null||value===undefined||value==="")return "";
 if(String(value)==="없음")return "없음";
 const raw=String(value).trim();
 const n=Number(raw);
 if(Number.isFinite(n)){
   if(n>=1900&&n<=2099)return String(n%100).padStart(2,"0");
   if(n>=0&&n<=99)return String(n).padStart(2,"0");
 }
 return raw;
}
function yearSortNumber(value){
 const y=Number(normalizeYearKey(value));
 if(!Number.isFinite(y))return 9999;
 return y>=82?1900+y:2000+y;
}
function receivesAllYearSetdeckEffects(p){
 // 임팩트는 연도 없음 카드이며 선택 연도와 무관하게 모든 연도 세트덱 효과를 받는다.
 // type 직접 판정까지 넣어 데이터/커스텀/클라우드 복원 경로가 달라도 동일하게 처리한다.
 return Boolean(p?.receivesAllYearEffects) || String(p?.type||"").trim()==="임팩트" || isYearlessImpact(p) || family(p)==="impact";
}
function receivesYearEffect(p,selectedYear){
 // 예전 정상 동작 규칙: 임팩트 카드는 카드 연도와 무관하게 모든 선택 연도 효과를 받는다.
 if(isYearlessImpact(p) || family(p)==="impact") return true;
 return normalizeYearKey(p.year)===normalizeYearKey(selectedYear);
}

function maxTraining(p){
 const f=family(p);
 if(f==="season"){
  const stars=cardStars(p);
  if(stars===3)return 16;
  if(stars===4)return 18;
  return 20; // 시즌 5성
 }
 if(f==="live")return 15+2*cardStars(p);
 return {signature:25,gold:25,impact:18,national:22,allstar:30,other:30}[f]||30;
}
function maxAwakening(p){
 return ["impact","signature","gold","national"].includes(family(p))?9:0;
}


