function enhancementTableKey(p,g=getGrowth(p)){
 const f=family(p),stars=cardStars(p);
 if(f==="live"&&stars===3)return "live3";
 if(f==="live"&&stars===4)return "live4";
 if(f==="live"&&stars===5)return "live5";
 if(f==="season"&&stars===3)return "season3";
 if(f==="season"&&stars===4)return "season4";
 if(f==="season"&&stars===5)return "season5";
 if(f==="allstar"&&stars===5)return "allstar5";
 if(f==="gold"&&stars===5)return "gold5";
 if(f==="gold"&&stars===4)return "gold4";
 if(f==="national"&&stars===5)return "national5";
 if(f==="signature"&&stars===5)return "signature5";
 if(f==="impact"&&stars===4)return "impact4";
 return null;
}
