function enhancementColumnKeys(p){
 const pitcher=["SP","RP","CP"].includes(p.pos);
 // 사진 표의 열 순서:
 // 타자 = 파워/정확/선구/주루/인내/수비
 // 투수 = 구속/제구/구위/변화/지구력/수비
 return pitcher
   ?["velocity","control","stuff","break","stamina","fielding"]
   :["power","contact","eye","baserun","patience","fielding"];
}
function ensureSeason3EnhanceRolls(p,g=getGrowth(p)){
 const keys=enhancementColumnKeys(p);
 if(!Array.isArray(g.season3EnhanceRolls))g.season3EnhanceRolls=[];
 for(let i=0;i<10;i++){
   if(!keys.includes(g.season3EnhanceRolls[i])){
     g.season3EnhanceRolls[i]=keys[Math.floor(Math.random()*keys.length)];
   }
 }
 return g.season3EnhanceRolls;
}
function setSeason3EnhanceRoll(stage,key){
 const p=players.find(x=>x.id===currentGrowId);if(!p)return;
 const g=getGrowth(p),keys=enhancementColumnKeys(p);
 if(enhancementTableKey(p,g)!=="season3"||!keys.includes(key))return;
 const rolls=ensureSeason3EnhanceRolls(p,g);
 rolls[Math.max(1,Math.min(10,Number(stage)||1))-1]=key;
 saveAll();renderGrow();renderPlayers();renderSquad();
}
function randomizeSeason3Enhance(){
 const p=players.find(x=>x.id===currentGrowId);if(!p)return;
 const g=getGrowth(p),keys=enhancementColumnKeys(p);
 if(enhancementTableKey(p,g)!=="season3")return;
 const rolls=ensureSeason3EnhanceRolls(p,g),lv=Math.max(0,Math.min(10,Number(g.enhance)||0));
 for(let i=0;i<lv;i++)rolls[i]=keys[Math.floor(Math.random()*keys.length)];
 saveAll();renderGrow();renderPlayers();renderSquad();
}
function season3EnhanceEditorHTML(p,g=getGrowth(p)){
 if(enhancementTableKey(p,g)!=="season3")return "";
 const lv=Math.max(0,Math.min(10,Number(g.enhance)||0)),rolls=ensureSeason3EnhanceRolls(p,g);
 const meta=statMeta(p),budget=lv*(lv+1)/2;
 if(!lv)return `<div class="notice" style="margin-top:8px">3성 시즌카드는 강화 단계마다 6개 기본 능력치 중 1개가 무작위로 선택되고, +N강 단계에서는 선택된 능력치가 +N 증가해. 강화 단계를 올리면 여기서 실제 결과를 맞출 수 있어.</div>`;
 return `<div class="notice" style="margin-top:8px">
  <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap">
   <b>3성 시즌 강화 랜덤 결과 · 총 +${budget}</b>
   <button type="button" onclick="randomizeSeason3Enhance()">현재 단계 랜덤 재추첨</button>
  </div>
  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(128px,1fr));gap:6px;margin-top:8px">
   ${Array.from({length:lv},(_,i)=>{
      const n=i+1;
      return `<label style="display:flex;align-items:center;gap:5px">+${n}강
       <select onchange="setSeason3EnhanceRoll(${n},this.value)" style="min-width:82px">
        ${meta.map(([k,l])=>`<option value="${k}" ${rolls[i]===k?"selected":""}>${l} +${n}</option>`).join("")}
       </select>
      </label>`;
   }).join("")}
  </div>
 </div>`;
}
function enhancementBonusMap(p,g=getGrowth(p)){
 const out={};for(const [k] of statMeta(p))out[k]=0;
 const key=enhancementTableKey(p,g),lv=Math.max(0,Math.min(10,Number(g.enhance)||0)),cols=enhancementColumnKeys(p);
 if(key==="season3"){
   const rolls=ensureSeason3EnhanceRolls(p,g);
   for(let n=1;n<=lv;n++){
     const k=rolls[n-1];
     if(k in out)out[k]+=n;
   }
   return out;
 }
 const table=key?ENHANCEMENT_TABLES[key]:null;
 if(!table)return out;
 for(let n=1;n<=lv;n++){
   const row=table[n]||[];
   cols.forEach((k,i)=>{if(k in out)out[k]+=Number(row[i]||0)});
 }
 return out;
}
function enhancementBonusTotal(p,g=getGrowth(p)){
 return Object.values(enhancementBonusMap(p,g)).reduce((a,b)=>a+(Number(b)||0),0);
}

