const PLAYER_PAGE_SIZE=100;
let playerPage=1;
function playerYearValue(p){if(isTop3Card(p)&&p.year!==null&&p.year!==undefined&&p.year!=="")return normalizeYearKey(p.year);return isYearlessImpact(p)?"없음":normalizeYearKey(p.year??"없음")}
function playerSearchText(p){
 const y=normalizeYearKey(p?.year);
 const fullYear=y&&y!=="없음"&&/^\d{2}$/.test(y)?`${Number(y)>=82?"19":"20"}${y}`:String(p?.year??"");
 return [p?.name,p?.team,p?.type,p?.series,p?.impactSeries,y,fullYear].filter(v=>v!==null&&v!==undefined&&v!=="").join(" ").toLowerCase();
}
function baseStatsHTML(p){
 return `<div class="base-stats">${statMeta(p).map(([k,l])=>`<div class="base-stat"><small>${l}</small><b>${p.stats?.[k]??"—"}</b></div>`).join("")}</div>`;
}
function renderPlayerPager(total){
 const pages=Math.max(1,Math.ceil(total/PLAYER_PAGE_SIZE));
 if(playerPage>pages)playerPage=pages;
 const el=$("playerPager");if(!el)return;
 el.innerHTML=`<button ${playerPage<=1?"disabled":""} onclick="playerPage=1;renderPlayers()">처음</button>
 <button ${playerPage<=1?"disabled":""} onclick="playerPage--;renderPlayers()">이전</button>
 <span class="page-now">${playerPage} / ${pages} 페이지 · 페이지당 ${PLAYER_PAGE_SIZE}장</span>
 <button ${playerPage>=pages?"disabled":""} onclick="playerPage++;renderPlayers()">다음</button>
 <button ${playerPage>=pages?"disabled":""} onclick="playerPage=${pages};renderPlayers()">마지막</button>`;
}

function filtered(){
 const q=$("q").value.trim().toLowerCase(),team=$("team").value,type=$("type").value,series=$("series").value,year=$("year").value,pos=$("pos").value,sf=$("statsFilter").value;
 return players.filter(p=>(!q||playerSearchText(p).includes(q))&&(!team||p.team===team)&&(!type||p.type===type)&&(!series||p.series===series)&&(!year||playerYearValue(p)===year)&&(!pos||p.pos===pos)&&(!sf||(sf==="known"?hasFullStats(p):!hasFullStats(p))));
}
function renderPlayers(){
 if(!$("players")||!$("players").getClientRects().length)return;
 const all=filtered().sort((a,b)=>searchStatScore(b)-searchStatScore(a)),pages=Math.max(1,Math.ceil(all.length/PLAYER_PAGE_SIZE));
 if(playerPage>pages)playerPage=pages;
 const start=(playerPage-1)*PLAYER_PAGE_SIZE,list=all.slice(start,start+PLAYER_PAGE_SIZE);
 $("count").textContent=`${all.length.toLocaleString()}장 / 전체 ${players.length.toLocaleString()}장`;
 $("players").innerHTML=list.map(p=>{
  const g=getGrowth(p),eff=effectiveTeam(p,g),fa=isFa(p,g);
  return `<div class="pcard">
   <div class="ovr"><div><b>${p.ovr??"—"}</b><small style="display:block">OVR</small></div></div>
   <div>
    <div class="pname">${esc(p.name)} ${displayYear(p)?`<span style="color:#7890ab;font-weight:600">${displayYear(p)}</span>`:`<span class="tag yearless">연도 없음</span>`}</div>
    <div class="meta">${esc(eff)}${fa?` (FA · 원소속 ${esc(p.team)})`:""} · ${esc(p.pos)} · ${esc(playerHandLabel(p))} · ${esc(p.type)}${p.type==="임팩트"?` · ${esc(p.series)}`:""}</div>
    <div class="tags">
     <span class="tag">세트덱 ${effectiveSetdeckScore(p)??"—"}</span>${p.type==="임팩트"?`<span class="tag" style="background:#819f0c;color:#fff6a6">${esc(p.series)}</span>`:""}
     <span class="tag db-source">사이트 DB</span>
     <span class="tag">훈련 ${g.training}/${maxTraining(p)}</span>
     <span class="tag">+${g.enhance}강</span>
     ${maxAwakening(p)?`<span class="tag">${g.awakening}각</span>`:""}
     ${specialBounds(p,g.faTeam)[1]?`<span class="tag">특훈 ${g.special}</span>`:""}
     ${lineupModeBonus(p)>0?`<span class="tag mode-bonus-tag">라인업효과 +${lineupModeBonus(p)}</span>`:""}
     ${family(p)==="gold"?`<span class="tag" style="background:#3a2e10;color:#ffe59c">${hasPreferredTeam()?`팀효과 ${esc(preferredTeam)}`:"팀효과 미적용"}</span>`:""}
    </div>
    ${baseStatsHTML(p)}
   </div>
   <div class="actions"><button class="mini" onclick="addPlayer('${p.id}')">＋ 배치</button><button class="mini" onclick="openGrow('${p.id}')">육성</button></div>
  </div>`
 }).join("")||`<div class="meta">검색 결과가 없어.</div>`;
 renderPlayerPager(all.length);
}


function lineupSetdeckInfo(mode=currentMode){
 const L=ensureLineupState(mode);
 let total=0,unknown=0,counted=0;
 for(const id of Object.values(L.slots)){
   if(!id)continue;
   const p=players.find(x=>x.id===id);if(!p)continue;
   const v=effectiveSetdeckScore(p);
   if(Number.isFinite(v)){total+=v;counted++}else unknown++;
 }
 return {total,unknown,counted,effectScore:Math.min(200,total)};
}



