  pendingPhotoFile=null; if($("photoFileInput"))$("photoFileInput").value="";
  renderAll();if(currentPickerSlot)renderPlayerPicker();renderPhotoPlayerMatches();renderSelectedPhotoState();toast("같은 이름·구단의 모든 카드 사진을 삭제했어.");
