function fillReferenceDummy(){
 const L=lineup();
 const used=new Set(
  Object.values(L.slots||{})
   .map(id=>players.find(p=>p.id===id))
   .filter(Boolean)
   .map(p=>String(p.name||"").trim())
   .filter(Boolean)
 );
 let added=0;
 const choose=slot=>{
  if(L.slots?.[slot])return;
  const list=players.filter(p=>slotAcceptsPlayer(slot,p)&&!used.has(String(p.name).trim()));
  list.sort((a,b)=>{
   const pref=canonicalPreferredTeam(),ta=a.team===pref?1:0,tb=b.team===pref?1:0;
   if(tb!==ta)return tb-ta;
   return searchStatScore(b)-searchStatScore(a)||(Number(b.ovr)||0)-(Number(a.ovr)||0);
  });
  const p=list[0];
  if(p){
   L.slots[slot]=p.id;
   used.add(String(p.name).trim());
   added++;
  }
 };
 FIELD.forEach(choose);
 BENCH.forEach(choose);
 PITCH.forEach(choose);
 autoOrder();
 saveAll();
 renderAll();
 toast(added?`빈 자리 ${added}칸에만 더미 데이터를 채웠어.`:"채울 빈 자리가 없어.");
}

