function setGrowthLevelExact(key,value){
 const p=players.find(x=>x.id===currentGrowId);if(!p)return;
 const g=getGrowth(p);
 if(key==="enhance"){
   g.enhance=Math.min(10,Math.max(0,Number(value)||0));
   // 각성은 +10강 상태에서만 유지된다.
   if(g.enhance<10)g.awakening=0;
 }
 if(key==="awakening"){
   if(g.enhance<10){
     g.awakening=0;
     toast("각성은 +10강화를 완료한 뒤에만 할 수 있어.");
   }else{
     g.awakening=Math.min(maxAwakening(p),Math.max(0,Number(value)||0));
   }
 }
 saveAll();
 renderGrow();
 renderPlayers();
 renderSquad();
}
