function stepGrowth(key,delta){
 const p=players.find(x=>x.id===currentGrowId),g=getGrowth(p);
 if(key==="training")g.training=Math.min(maxTraining(p),Math.max(0,g.training+delta));
 if(key==="enhance"){
   g.enhance=Math.min(10,Math.max(0,g.enhance+delta));
   if(g.enhance<10)g.awakening=0;
 }
 if(key==="awakening"){
   if(g.enhance<10){
     g.awakening=0;
     toast("각성은 +10강화를 완료한 뒤에만 할 수 있어.");
   }else{
     g.awakening=Math.min(maxAwakening(p),Math.max(0,g.awakening+delta));
   }
 }
 if(key==="special"){const [min,max]=specialBounds(p,g.faTeam);g.special=Math.min(max,Math.max(min,g.special+delta))}
 saveAll();renderGrow();renderPlayers();renderSquad();
}
