function toast(msg){const d=document.createElement("div");d.textContent=msg;Object.assign(d.style,{position:"fixed",left:"50%",bottom:"20px",transform:"translateX(-50%)",background:"#101d2d",border:"1px solid #3d6488",color:"#eef8ff",padding:"9px 13px",borderRadius:"9px",zIndex:99,fontSize:"11px"});document.body.appendChild(d);setTimeout(()=>d.remove(),1900)}
const CUSTOM_STORE='v26_custom_cards_v1';
const CUSTOM_TYPES=['임팩트','시그니처','골든글러브','국가대표','LIVE','라이브 올스타','시즌'];
let customEditingId=null;
function customCardRule(type){
 return ({'임팩트':{stars:[4],base:4,year:false},'골든글러브':{stars:[4,5],base:3,year:true},'시그니처':{stars:[5],base:5,year:true},'국가대표':{stars:[5],base:4,year:true},'LIVE':{stars:[3,4,5],base:null,year:true},'라이브 올스타':{stars:[5],base:null,year:true},'시즌':{stars:[3,4,5],base:4,year:true}})[type]||{stars:[1,2,3,4,5],base:null,year:true};
}
function applyCustomCardRule(){
 const r=customCardRule($('customType').value),stars=$('customStars'),old=Number(stars.value);
 const signature=r.stars.join(',');
 if(stars.dataset.allowed!==signature){stars.replaceChildren(...r.stars.map(n=>new Option(n+'성',n)));stars.dataset.allowed=signature;}
 stars.value=r.stars.includes(old)?old:r.stars[0];stars.disabled=r.stars.length===1;
 $('customDeck').disabled=r.base!==null;if(r.base!==null)$('customDeck').value=r.base;
 $('customYear').disabled=!r.year;
}
function customBaseOvrFromStats(stats,pos){
 const meta=['SP','RP','CP'].includes(pos)?PIT_META:BAT_META;
 const values=meta.map(([k])=>Number(stats?.[k]));
 if(values.some(v=>!Number.isFinite(v)))return null;
 return Math.floor(values.reduce((a,b)=>a+b,0)/values.length);
}
function updateCustomOvrFromStats(){
 const pos=$('customPos')?.value||'CF';
 const meta=['SP','RP','CP'].includes(pos)?PIT_META:BAT_META;
 const stats=Object.fromEntries(meta.map(([k])=>[k,$('customStat-'+k)?.value]));
 const ovr=customBaseOvrFromStats(stats,pos);
 const input=$('customOvr');if(input&&ovr!==null)input.value=ovr;
 return ovr;
}
function validateCustomCard(raw){
 if(!raw||typeof raw!=='object')throw Error('선수 데이터 형식이 올바르지 않아.');
 const name=String(raw.name||'').trim();
 if(!name||name.length>40)throw Error('선수 이름은 1~40자로 입력해 줘.');
 if(!TEAMS.includes(raw.team)||!POS.includes(raw.pos)||!CUSTOM_TYPES.includes(raw.type))throw Error('구단·포지션·카드 종류를 확인해 줘.');
 const num=(v,min,max,label)=>{const n=Number(v);if(v===''||!Number.isInteger(n)||n<min||n>max)throw Error(label+' 값을 확인해 줘.');return n;};
 const rule=customCardRule(raw.type);
 const stars=rule.stars.includes(Number(raw.stars))?Number(raw.stars):rule.stars[0],setdeck=rule.base??num(raw.setdeck,0,100,'세트덱');
 const year=raw.type==='임팩트'?null:num(raw.year,0,2099,'연도');
 const keys=['SP','RP','CP'].includes(raw.pos)?PIT_META:BAT_META;
 const stats=Object.fromEntries(keys.map(([k,l])=>[k,num(raw.stats?.[k],1,200,l)]));
 const ovr=Math.floor(Object.values(stats).reduce((a,b)=>a+b,0)/Object.values(stats).length);
 const series=raw.type==='임팩트'?String(raw.series||'커스텀').trim().slice(0,40):'';
 const pitcher=keys===PIT_META;
 const bats=['','우','좌','양'].includes(raw.bats)?raw.bats:'';
 const throws=['','우','좌'].includes(raw.throws)?raw.throws:'';
 const id=/^custom-[a-z0-9-]{1,80}$/.test(raw.id||'')?raw.id:'custom-'+crypto.randomUUID();
 return {id,name,team:raw.team,pos:raw.pos,type:raw.type,series,impactSeries:series,year,stars,ovr,setdeck,stats,role:pitcher?'pitcher':'batter',bats:pitcher?'':bats,throws:pitcher?throws:'',custom:true,sourceLevel:'custom'};
}
function commitCustomCards(cards){
 const clean=cards.map(validateCustomCard);
 if(new Set(clean.map(p=>p.id)).size!==clean.length)throw Error('중복된 선수 ID가 있어.');
 localStorage.setItem(CUSTOM_STORE,JSON.stringify(clean));
 for(let i=players.length-1;i>=0;i--)if(players[i].custom)players.splice(i,1);
 players.push(...clean);
}
function loadCustomCards(){
 try{const raw=JSON.parse(localStorage.getItem(CUSTOM_STORE)||'[]');if(!Array.isArray(raw))throw Error();players.push(...raw.map(validateCustomCard));}
 catch(e){console.warn('Custom cards could not be loaded');setTimeout(()=>toast('커스텀 선수를 읽지 못했어. 백업 파일을 불러와 줘.'),500);}
}
function openCustomCards(id=null){
 customEditingId=id;
 const p=players.find(p=>p.custom&&p.id===id);
 const d=$('customDialog');
 if(!d.open)d.showModal();
 const set=(id,v)=>$(id).value=v;
 set('customName',p?.name||'');set('customType',p?.type||'임팩트');set('customTeam',p?.team||(canonicalPreferredTeam()||TEAMS[0]));
 set('customPos',p?.pos||(currentPickerSlot?pickerRequiredPos(currentPickerSlot):'CF'));
 if(!POS.includes($('customPos').value))set('customPos','CF');
 const starInput=$('customStars');starInput.replaceChildren(...[1,2,3,4,5].map(n=>new Option(n+'성',n)));delete starInput.dataset.allowed;
 set('customStars',p?.stars||4);set('customYear',p?.year??26);set('customOvr',p?.ovr||70);set('customDeck',p?.setdeck??4);set('customSeries',p?.series||'');
 set('customBattingHand',p?.bats||'');set('customPitchingHand',p?.throws||p?.throwingHand||'');
 renderCustomStats(p?.stats);updateCustomPreview();renderCustomList();$('customName').focus();
}
function renderCustomStats(stats){
 const pitcher=['SP','RP','CP'].includes($('customPos').value),meta=pitcher?PIT_META:BAT_META;
 $('customBatHandRow').style.display=pitcher?'none':'';
 $('customThrowHandRow').style.display=pitcher?'':'none';
 $('customStats').innerHTML=meta.map(([k,l])=>`<label>${l}<input id="customStat-${k}" type="number" min="1" max="200" step="1" value="${Number(stats?.[k])||70}" required oninput="updateCustomOvrFromStats();updateCustomPreview()"></label>`).join('');
}
function readCustomForm(){
 const meta=['SP','RP','CP'].includes($('customPos').value)?PIT_META:BAT_META;
 const pitcher=['SP','RP','CP'].includes($('customPos').value);
 const stats=Object.fromEntries(meta.map(([k])=>[k,$('customStat-'+k).value]));
 const ovr=customBaseOvrFromStats(stats,$('customPos').value);
 return {id:customEditingId||undefined,name:$('customName').value,type:$('customType').value,team:$('customTeam').value,pos:$('customPos').value,stars:$('customStars').value,year:$('customYear').value,ovr:ovr??$('customOvr').value,setdeck:$('customDeck').value,series:$('customSeries').value,bats:pitcher?'':$('customBattingHand').value,throws:pitcher?$('customPitchingHand').value:'',stats};
}
function updateCustomPreview(){
 applyCustomCardRule();
 updateCustomOvrFromStats();
 const r=readCustomForm();$('customYear').disabled=r.type==='임팩트';$('customSeries').disabled=r.type!=='임팩트';
 const preview=$('customPreview');
 [...preview.classList].filter(c=>c.startsWith('preview-')).forEach(c=>preview.classList.remove(c));
 const previewClass=r.type==='임팩트'?'impact':r.type==='시그니처'?'signature':r.type==='골든글러브'?'gold':r.type==='국가대표'?'national':r.type==='라이브 올스타'?'allstar':r.type==='시즌'?'season':r.type==='LIVE'?`live-${Number(r.stars)}`:'other';
 preview.classList.add('preview-'+previewClass);
 const pitcher=['SP','RP','CP'].includes(r.pos),hand=pitcher?(r.throws?r.throws+'투':'투구 미지정'):(r.bats?r.bats+'타':'타격 미지정');
 preview.textContent='★'.repeat(Number(r.stars))+'\nOVR '+r.ovr+'\n'+r.team+' · '+r.pos+' · '+hand+'\n'+(r.series||r.type)+'\n'+(r.name||'선수 이름')+(r.type==='임팩트'?'':" ’"+String(r.year).slice(-2));
 $('customSave').textContent=customEditingId?'변경 저장':'선수 생성';
}
function refreshCustomSearch(){
 const s=$('pickerSeries'),old=s.value;s.replaceChildren(new Option('전체',''));
 [...new Set(players.filter(p=>p.type==='임팩트').map(p=>p.series).filter(Boolean))].sort().forEach(v=>s.add(new Option(v,v)));s.value=old;
 renderAll();renderPlayers();
}
function saveCustomCard(event){
 event.preventDefault();
 try{
 const card=validateCustomCard(readCustomForm());
 const previous=players.find(p=>p.id===card.id);
 if(previous&&Object.values(lineup().slots).includes(card.id)&&previous.pos!==card.pos)throw Error('배치 중인 선수는 라인업에서 뺀 뒤 포지션을 변경해 줘.');
 const next=players.filter(p=>p.custom&&p.id!==card.id);next.push(card);commitCustomCards(next);
 delete growth[card.id];refreshCustomSearch();openCustomCards(card.id);toast('커스텀 선수를 저장했어. 선수 선택창에서 이름으로 검색할 수 있어.');
 }catch(e){alert(e.message||'저장 공간이 부족해. 백업 후 확인해 줘.');}
}
function renderCustomList(){
 const box=$('customList');box.replaceChildren();
 players.filter(p=>p.custom).forEach(p=>{
 const row=document.createElement('div');row.className='custom-list-row';const text=document.createElement('span');text.textContent=p.name+' · '+p.team+' · '+p.pos+' · '+p.type;row.append(text);
 const edit=document.createElement('button');edit.type='button';edit.textContent='편집';edit.onclick=()=>openCustomCards(p.id);row.append(edit);
 const del=document.createElement('button');del.type='button';del.textContent='삭제';del.onclick=()=>deleteCustomCard(p.id);row.append(del);box.append(row);
 });
 if(!box.childElementCount)box.textContent='아직 만든 선수가 없어.';
}
function deleteCustomCard(id){
 if(!confirm('이 커스텀 선수를 삭제할까? 라인업에서도 빠져.'))return;
 try{commitCustomCards(players.filter(p=>p.custom&&p.id!==id));for(const L of Object.values(lineups))for(const s of Object.keys(L.slots))if(L.slots[s]===id)delete L.slots[s];delete growth[id];refreshCustomSearch();openCustomCards();}catch(e){alert('삭제 내용을 저장하지 못했어.');}
}
function exportCustomCards(){download('v26-custom-players.json',JSON.stringify({format:'v26-custom-v1',cards:players.filter(p=>p.custom)},null,2),'application/json');}
async function importCustomCards(input){
 try{
 const file=input.files[0];if(!file)return;if(file.size>5000000)throw Error('5MB 이하 파일을 선택해 줘.');
 const parsed=JSON.parse(await file.text());if(parsed.format!=='v26-custom-v1'||!Array.isArray(parsed.cards)||parsed.cards.length>2000)throw Error('커스텀 선수 백업 파일이 아니야.');
 const incoming=parsed.cards.map(validateCustomCard),existing=players.filter(p=>p.custom),ids=new Set(existing.map(p=>p.id));
 // Keep existing cards intact; a conflicting backup becomes a separately editable copy.
 for(const p of incoming){if(ids.has(p.id))p.id='custom-'+crypto.randomUUID();ids.add(p.id);existing.push(p);}
 commitCustomCards(existing);refreshCustomSearch();renderCustomList();toast(incoming.length+'명의 커스텀 선수를 불러왔어.');
 }catch(e){alert(e.message||'파일을 읽지 못했어.');}finally{input.value='';}
}
function initCustomCards(){
 for(const [id,values] of [['customType',CUSTOM_TYPES],['customTeam',TEAMS],['customPos',POS]])fill(id,values,false);
 loadCustomCards();
}

initCustomCards();
initViewMode();

/* ===== Cloud lineup bridge v11.2 ===== */
function cloudLineupSnapshot(){
 const payload=lineupPayload(currentMode);
 return {
  schema:"kbo-cloud-lineup-v1",
  appVersion:"11.7",
  savedAt:new Date().toISOString(),
  mode:currentMode,
  modeName:MODES[currentMode]||currentMode,
  preferredTeam,
  playerCount:payload.players?.length||0,
  playerNames:(payload.players||[]).map(x=>x.name).filter(Boolean),
  payload
 };
}
function loadCloudLineupSnapshot(snapshot){
 const payload=snapshot?.payload||snapshot;
 if(!payload||typeof payload!=="object")throw Error("저장된 라인업 데이터가 올바르지 않아.");
 const targetMode=(payload.mode&&Object.hasOwn(MODES,payload.mode))?payload.mode:currentMode;
 const previousLineups=lineups;
 const count=importLineupData(payload);
 // importLineupData()가 만든 복원 완료 상태를 확보한다.
 // 이 앱은 ensureLineupState()에서 ranking을 모든 모드의 기준 상태로 사용하므로,
 // 클라우드 불러오기에서도 ranking에 복원 상태를 넣어야 슬롯이 다시 빈 상태로 덮이지 않는다.
 const importedState=lineups[currentMode]||lineups.ranking;
 if(!importedState||!importedState.slots)throw Error("복원된 라인업 상태를 찾지 못했어.");
 lineups=previousLineups;
 lineups.ranking=importedState;
 for(const mode of Object.keys(MODES))lineups[mode]=importedState;
 currentMode=targetMode;
 ensureLineupState(currentMode);
 localStorage.setItem("v26_mode",currentMode);
 $("preferredTeam").value=preferredTeam;
 refreshCustomSearch();renderTabs();updateChoiceGridTriggers();renderAll();closeExport();
 toast(`${count}명 라인업을 계정 저장본에서 불러왔어.`);
 return count;
}
window.KBOCloudBridge={
 getSnapshot:cloudLineupSnapshot,
 loadSnapshot:loadCloudLineupSnapshot,
 getCurrentMode:()=>currentMode,
 getModeName:()=>MODES[currentMode]||currentMode,
 getPreferredTeam:()=>preferredTeam
};
window.dispatchEvent(new Event("kbo-cloud-bridge-ready"));

init();
initPlayerPhotoFeature();

;(()=>{const el=document.getElementById("app-loading");if(el)el.remove();})();
